          "PDF के भीतर एक पेज ट्री होता है: रेफ़रेंस की एक क्रमबद्ध सूची, जिसका हर सदस्य एक पेज ऑब्जेक्ट की ओर इशारा करता है, और वह ऑब्जेक्ट आगे अपने कंटेंट स्ट्रीम, फ़ॉन्ट और इमेज की ओर। पेज हटाना इसी ट्री पर काम है — सूची से रेफ़रेंस निकल जाता है — जबकि उस पेज के कंटेंट स्ट्रीम, फ़ॉन्ट और इमेज बेबस रेफ़रेंस होकर छोड़ दिए जाते हैं। बचे हुए पेजों के बारे में कुछ भी दोबारा नहीं बनाया, री-एनकोड या बदला जाता।",
