          "अक्षर-स्तर का उलटाव पहेली और खेल-डिज़ाइन में (दर्पण-लेखन, दर्पण में सही पढ़े जाने वाले छिपे संदेश), टेस्टिंग में (सत्यापनकर्ताओं को उलटे स्ट्रिंग खिलाकर जाँचना कि वे ठुकराते हैं), और भोले स्ट्रिंग-मिलान फ़िल्टरों से बचने में उभरता है — जो यह भी बताता है कि reverse-text क्लासिक pen-test चाल है जानने लायक।",
