          "MD5 Ron Rivest ने 1991 में तेज़ 128-बिट संदेश-digest के रूप में गढ़ा, और एक दशक तक वह वेब का डिफ़ॉल्ट hash था। वही रफ़्तार उसकी बिक्री-बिंदु थी — और आख़िरकार उसका विनाश। चूँकि वह डेटा जल्दी प्रोसेस करता है, हमलावर प्रति-सेकंड विशाल इनपुट आज़मा सकते हैं, और चूँकि उसकी भीतरी संरचना में ज्ञात कमज़ोरियाँ हैं, उन्हें टकराव-प्रतिरोध तोड़ने को बल-प्रयोग भी नहीं करना पड़ता।",
