          "बल्क या स्वचालित रूपांतरणों के लिए वही लाइब्रेरी Node स्क्रिप्ट में स्थापित होती है; यह पेज उसी काम का अंतःक्रियाशील सामने-का सिरा है। किसी भी तरह तरीक़ा आपकी मशीन पर रहता है — उपयुक्त चाहे स्रोत सार्वजनिक changelog हो या ऐसा दस्तावेज़ जिसे कोई और देखना नहीं चाहिए।",
