          "कुछ नापें इसलिए दोहराई जाती हैं कि प्लेटफ़ॉर्म उन्हें तय करते हैं। 1200×630 आयत canonical open-graph / सोशल-प्रीव्यू कार्ड नाप है — वह अनुपात जिसमें ज़्यादातर प्लेटफ़ॉर्म लिंक-प्रीव्यू क्रॉप करते हैं। 256×256 और मिलते-जुलते दो की घातें avatar और आइकन-स्लॉटों से मेल खाती हैं। 16:9 आयत (1280×720) वीडियो-एम्बेडों से सँगठित होते हैं। अंतिम संपत्ति के अनुपात वाला placeholder चुनने का मतलब है मॉकअप असली इमेज आने पर कभी नहीं खिसकता, क्योंकि लेआउट-पुनःप्रवाह वह महँगा बग है जिसे रोकने के लिए ये इमेजें हैं।",
