          "कुंजी को hash के साथ भोले ढंग से जोड़ना — SHA-256(key + message) — ज्ञात कमज़ोरियाँ रखता है: डेटा जोड़कर फिर-गणना संभव हो सकती है अगर hash की भीतरी अवस्था रिसे, और ब्लॉक-सीमा पर कुंजी-टकराव अटपटे हैं। HMAC, RFC 2104 (1997) में और बाद में NIST FIPS 198 में मानकित, दोनों टालता है कुंजी को तय संरचना में दो बार hash करके: पहले संदेश को भराई-स्थिरांक (opad) से XOR की गई कुंजी के साथ hash किया जाता है, फिर वही नतीजा दूसरे स्थिरांक (ipad) से XOR की गई कुंजी के साथ फिर hash होता है।",
