          "समर्थन-टिकटें भरने वाली सत्यापन-विफलता बाइट-बेमेल होती है, टूटा एल्गोरिदम नहीं। सर्विसें कच्चा अनुरोध-बॉडी हस्ताक्षरित करती हैं — भेजे गए सटीक बाइट। अगर आपका framework सत्यापन से पहले JSON फिर-serialize करे (कुंजियाँ फिर क्रमित करके, सफ़ेद-जगह बदलकर, line-endings बदलकर), तो फिर-गणित हस्ताक्षर कभी मेल नहीं खाएगा। बिना-parse बॉडी से मिलाएँ, और ऐसे proxies या body parsers से सावधान रहें जो उसे “मददगारी” से पहले सामान्य कर देते हैं।",
