    intro: ['भरे हुए PDF फ़ॉर्म इंटरैक्टिव होते हैं: मान अलग फ़ील्ड ऑब्जेक्ट में रहते हैं जिन्हें कुछ रीडर फ़ाइल आगे भेजते समय रीसेट, खो देते या दोबारा क्रमित कर देते हैं। pdf-lib से फ्लैटन करने पर हर फ़ील्ड सीधे अपने पृष्ठ पर बन जाता है, ताकि आपने जो भरा वही हर रीडर दिखाए — कई जॉब, टैक्स और फ़ाइलिंग पोर्टल की यह अनिवार्य आवश्यकता है।',
        'प्रोसेस किया गया दस्तावेज़ वैसा ही दिखता है पर अब उसमें फ़ॉर्म फ़ील्ड नहीं होते: कुछ भी खाली, बदला या दोबारा सबमिट नहीं किया जा सकता। सब कुछ pdf-lib से आपके डिवाइस पर चलता है; फ़ाइल ब्राउज़र छोड़ती नहीं। अगर PDF में कोई भरने योग्य फ़ील्ड नहीं है, तो टूल बेकार प्रति बनाने के बजाय यह बता देता है।'],
