          "तब flatten करें जब दस्तावेज़ पूरा और बाहर जाने वाला हो: पूरा भरा आवेदन-फ़ॉर्म, डाक होने वाला हस्ताक्षरित संविदा, ऐसा समीक्षित ड्राफ़ट जिसकी टिप्पणियाँ लापरवाह printer से बचनी चाहिए। Flattening संयोजन से पहले का मानक कदम भी है: ऐसी दो फ़ाइलें मर्ज करना जिनमें एक में form फ़ील्ड हों, टकराते फ़ील्ड-नाम पैदा कर सकता है, और फ़्लैटन किए इनपुट निष्क्रिय पेजों की तरह मर्ज होते हैं।",
