    deepDive: [
      {
        heading: "Token लंबाई और बल-प्रयोग का हिसाब",
        paragraphs: [
          "Token की सुरक्षा उसकी एन्ट्रॉपी है, और एन्ट्रॉपी सादा हिसाब है: अक्षर-सेट-नाप का log2 × लंबाई। 62-अक्षर alphanumeric सेट प्रति-अक्षर लगभग 5.95 बिट देता है, इसलिए 32 अक्षर ~190 बिट है — ऐसी खोज-अंतरिक्षा जिसे कोई कल्पनीय हार्डवेयर चल नहीं सकता। यहाँ तक कि 16 alphanumeric अक्षर (~95 बिट) ऑनलाइन अंदाज़ा और ज़्यादातर ऑफ़लाइन दृश्यों से आराम से ऊपर बैठते हैं।",
          "लंबाई वास्तव में दो असलियतों के मुक़ाबले मार्जिन ख़रीदती है: token आंशिक रिसता है (एक लॉग, referrer हेडर, एक स्क्रीनशॉट) और एल्गोरिदम सुधरते हैं। 30 बिट रिसे 128-बिट token के पास अब भी 98 हैं — ठीक; 10 रिसे 40-बिट token लगभग ख़त्म। इसीलिए ईमानदार अनुशंसा है “आपकी सोच से ज़्यादा”: एन्ट्रॉपी सस्ती है, उजागर होने के बाद घुमाव महँगे।",
          "एक आपत्ति जिसे दर्शक नहीं देख सकता: एन्ट्रॉपी पैदाइश-प्रक्रिया नापती है, सलूक़ नहीं। बेदाग़ यादृच्छिक 190-बिट token टिकट में पेस्ट हो जाए, repository में कमिट हो जाए या proxy लॉग कर ले, तो उसकी प्रभावी ताक़त घुमाए जाने तक शून्य है। लंबाई अंदाज़ा लगाने से बचाती है; स्वच्छता बाक़ी सबसे।",
        ],
      },
      {
        heading: "अपारदर्शी tokens बनाम UUIDs: एक ही काम नहीं",
        paragraphs: [
          "किसी भी यादृच्छिक-दिखने वाली स्ट्रिंग को राज़ मान लेना आकर्षक है, पर पहचानकर्ता दो परिवारों में बँटते हैं उलटी आवश्यकताओं वाले। UUID और ULID कहीं से भी, समांतर रूप से पैदा होने और (ULID के लिए) समय से क्रमित होने के लिए गढ़े गए — यानी वे जानबूझकर जानकारी कोडित करते हैं: संस्करण-बिट, समय-मुद्राएँ, कभी काउंटर। अनुमान-योग्यता उनकी चिंता नहीं।",
          "अपारदर्शी यादृच्छिक token उलटा है: वह कुछ भी कोडित नहीं करता और केवल अपूर्वानुमेय होने के लिए होता है। API कुंजियों, bearer tokens, सत्र-पहचानकर्ताओं और webhook राज़ों के लिए वही सही मूल-कार्य है। UUID v1 को session ID के रूप में इस्तेमाल करने से मसलन मशीन का MAC पता और पैदाइश-समय रिसता है — असली ऐतिहासिक कमज़ोरी-श्रेणी है, सैद्धांतिक नहीं।",
          "Hex एक टिप्पणी का हक़दार है: वह बाइटों पर सटीक मैप होता है (32 hex अक्षर = 16 यादृच्छिक बाइट), इसीलिए इतने प्रोटोकॉल राज़ उसी रूप में दिखाते हैं, पर वह प्रति-अक्षर केवल 4 बिट ले जाता है — alphanumeric की आधी घनत्व। प्रतीक घनत्व बढ़ाते हैं पर ऐसे उपभोक्ताओं को तोड़ते हैं जो हेडर URL-एनकोड नहीं करते; वही सेट चुनें जिसे आपका उपभोक्ता वास्तव में स्वीकारता है।",
        ],
      },
      {
        heading: "Math.random राज़ों पर क्यों विफल होता है, और लोकल पैदाइश",
        paragraphs: [
          "Math.random() ऐसा pseudo-random जनरेटर है जिसकी भीतरी अवस्था परिमित और पुनर्गठन-योग्य है: जो हमलावर काफ़ी आउटपुट देख ले — या लगभग जानता हो token कब पैदा हुआ — वह उसे दोबारा पैदा कर सकता है। उस पर बने tokens यादृच्छिक दिखे हैं और असली घटनाओं में भविष्यवाणी किए गए हैं; शॉर्टकट ट्यूटोरियलों और Stack Overflow उत्तरों में बचा रहता है — ठीक यही कारण है कि वह बार-बार होता रहता है।",
          "crypto.getRandomValues ब्राउज़र का रूपांतरिक-सुरक्षा स्रोत है, जिसे OS हार्डवेयर-एन्ट्रॉपी से बीजित करता है और जिसे ऐसे गढ़ा गया है कि कोई पर्यवेक्षक पिछले आउटपुटों से अगला भविष्यवाणी न कर सके। यह टूल उसी से खिंचाव कर बाइट बिना पक्षपात आपके चुने चारसेट पर मैप करता है, फिर निकली एन्ट्रॉपी दिखाता है ताकि संख्या दावा नहीं, ऑडिट-योग्य हो।",
          "पैदाइश लोकल भी है: tokens आपके ब्राउज़र की मेमोरी में पैदा होते हैं और कभी प्रसारित नहीं होते, इसलिए यहाँ पैदा प्रोडक्शन राज़ किसी तीसरे पक्ष के सर्वर-लॉग में कभी नहीं उतरता। पेज फिर-लोड करें और वे ग़ायब — उसी सत्र में उन्हें अपने secret store में कॉपी करें। दीर्घ-जीवी प्रमाणपत्रों के लिए वह store स्थायी घर है; जनरेटर जन्मस्थान है, अभिलेख नहीं।",
        ],
      },
    ],
